import hashlib,os,re,subprocess,sys
fail=[]
T=d['target']
def raw(p): return open(p,'rb').read()
def txt(p): return raw(p).decode('utf-8')
def head(p): return subprocess.run(['git','show','HEAD:'+p],capture_output=True).stdout
for p,h in d['readOnlySourceSha256'].items():
    if hashlib.sha256(raw(p)).hexdigest()!=h: fail.append('source drift '+p)
if hashlib.sha256(head(T)).hexdigest()!=d['preEdit']['blobSha256']: fail.append('blob hash')
if hashlib.sha256(raw(T)).hexdigest()!=d['final']['workingTreeSha256']: fail.append('final hash')
r=raw(T)
if r.count(b'\r\n')!=r.count(b'\n'): fail.append('line endings not uniformly CRLF')
cur=txt(T).replace('\r\n','\n'); old=head(T).decode('utf-8')
if len(cur.splitlines())>d['lineCaps'][T]: fail.append('size')
def sect(t,a,b):
    i=t.index(a); j=t.index(b) if b else len(t); return t[i:j]
# protected setup block: section 4 identical except the two allowed lines
s_old=sect(old,'## 4. Bắt đầu ngay','## 5.'); s_new=sect(cur,'## 4. Bắt đầu ngay','## 5.')
for o,n in d['allowedSetupEdits']:
    if s_old.count(o)!=1 or s_new.count(n)!=1: fail.append('allowed edit not found '+o[:30])
    s_old=s_old.replace(o,'@@'); s_new=s_new.replace(n,'@@')
if s_old!=s_new: fail.append('setup block changed beyond allowed edits')
for cmd in d['protectedSetupTokens']:
    if cmd not in s_new: fail.append('setup token missing '+cmd)
# untouched narrative
for a,b in d['unchangedSections']:
    if sect(old,a,b)!=sect(cur,a,b): fail.append('unexpected change in '+a)
for t in d['mustNotContain']:
    if t in cur: fail.append('stale claim: '+t)
for t in d['mustContain']:
    if t not in cur: fail.append('missing: '+t)
def slug(h):
    h=h.strip().lower(); h=re.sub(r'[^\w\s-]','',h); return re.sub(r'\s','-',h)
def links(t):
    return [m.group(1) for m in re.finditer(r'\]\(([^)\s]+)\)',t)]
def bad(t):
    out=[]
    for l in links(t):
        if l.startswith(('http:','https:','mailto:')): continue
        f,_,a=l.partition('#')
        p=os.path.normpath(os.path.join(os.path.dirname(T),f)) if f else T
        if not os.path.exists(p): out.append(l); continue
        if a and os.path.isfile(p):
            hs=[slug(m.group(1)) for m in re.finditer(r'(?m)^#{1,6}\s+(.*)$',open(p,encoding='utf-8').read())]
            if a not in hs: out.append(l)
    return out
new_bad=[l for l in bad(cur) if l not in bad(old)]
if new_bad: fail.append('new broken links '+repr(new_bad))
st=subprocess.run(['git','status','--short','--untracked-files=all'],capture_output=True,text=True).stdout.splitlines()
if sorted(x[3:] for x in st)!=sorted(d['exactPaths']): fail.append('path set '+repr(st))
print('FAIL' if fail else 'PASS_STATIC_ONLY',ascii(fail),'preexistingBrokenLinks',ascii(bad(old)))
sys.exit(1 if fail else 0)
